package io.github.rebrowser.outlook;
import org.junit.Test;
import static org.junit.Assert.*;
import io.github.rebrowser.bootstrap.*;
import io.github.rebrowser.core.*;
import java.lang.reflect.*;
import java.util.concurrent.atomic.*;
/** Actual core private-operation/real task lifecycle; native source/mailbox/current authority/
 * journal/transport are SYNTHETIC. NO real Microsoft account, mail mutation or effect receipt. */
public final class OfficialMailActionsHostTest {
 static final class F implements AutoCloseable {
  final ComponentGate gate=ComponentGate.forNativeSource(ProcessRole.MAIN,()->ComponentGate.SourceView.acceptedNative(this,new byte[16]));final MailAccountCatalog accounts=new MailAccountCatalog(gate.captureDataEpoch(gate.requireBusiness()));final MailAccountCatalog.PersistenceScope scope=accounts.capturePersistenceScope(accounts.select(accounts.createNativeLocalAccount("synthetic")),1);final Object taskFixture;final TaskCoordinator.Submission task;final AtomicBoolean allowed=new AtomicBoolean(true);final AtomicInteger handoffs=new AtomicInteger(),stops=new AtomicInteger();final OfficialMailActions actions;boolean fail;
  F()throws Exception{Class<?> c=Class.forName("io.github.rebrowser.data.DownloadMetadataStoreTest$NativeTask");Constructor<?> ctor=c.getDeclaredConstructor(ComponentGate.class);ctor.setAccessible(true);taskFixture=ctor.newInstance(gate);Field t=c.getDeclaredField("task");t.setAccessible(true);task=(TaskCoordinator.Submission)t.get(taskFixture);actions=new OfficialMailActions(scope,(s,a,item,folder,owner)->{if(!allowed.get())throw new SecurityException("synthetic authority revoked");},new OfficialMailActions.NativeOfficialWriteAdapter(){public void handoffOnce(OfficialMailActions.Operation operation)throws Exception{handoffs.incrementAndGet();if(fail)throw new java.io.IOException("synthetic unknown handoff");}public void requestStopOwned(OfficialMailActions.Operation operation){stops.incrementAndGet();}});}
  OfficialMailActions.Operation send(){return actions.prepareNativeSend(task,"recipient@example.test","subject","plain\nbody");}
  public void close()throws Exception{((AutoCloseable)taskFixture).close();}
 }
 @Test public void nativeFixedSendIsNotAutomaticEffectOrActualEnd()throws Exception{try(F f=new F()){OfficialMailActions.Operation o=f.send();assertEquals("plain\nbody",o.nativePlainBody());assertEquals(0,f.handoffs.get());assertEquals(OfficialMailActions.HandoffObservation.HANDOFF_CALL_RETURNED,f.actions.dispatchPreparedOnce(o));assertEquals(1,f.handoffs.get());assertFalse(f.task.nativeOwner().hasReportedActualDomainEnd());}}
 @Test public void sameOperationCannotRetryOrChooseAnotherRoute()throws Exception{try(F f=new F()){OfficialMailActions.Operation o=f.send();f.actions.dispatchPreparedOnce(o);assertThrows(SecurityException.class,()->f.actions.dispatchPreparedOnce(o));assertEquals(1,f.handoffs.get());}}
 @Test public void exceptionUnknownRetainsActualWorkAndSpentRoute()throws Exception{try(F f=new F()){f.fail=true;OfficialMailActions.Operation o=f.send();assertEquals(OfficialMailActions.HandoffObservation.HANDOFF_OUTCOME_UNKNOWN,f.actions.dispatchPreparedOnce(o));assertFalse(f.task.nativeOwner().hasReportedActualDomainEnd());assertThrows(SecurityException.class,()->f.actions.dispatchPreparedOnce(o));}}
 @Test public void currentAuthorityRevocationBlocksPayloadAndHandoff()throws Exception{try(F f=new F()){OfficialMailActions.Operation o=f.send();f.allowed.set(false);assertThrows(SecurityException.class,o::nativePlainBody);assertThrows(SecurityException.class,()->f.actions.dispatchPreparedOnce(o));assertEquals(0,f.handoffs.get());}}
 @Test public void changedNativeAccountSelectionCannotRetargetOldOperation()throws Exception{try(F f=new F()){OfficialMailActions.Operation o=f.send();f.accounts.select(f.accounts.createNativeLocalAccount("another"));assertThrows(SecurityException.class,()->f.actions.dispatchPreparedOnce(o));assertEquals(0,f.handoffs.get());}}
 @Test public void foreignTaskCannotSupplyAnotherEpochSourceAuthority()throws Exception{try(F f=new F();F other=new F()){assertThrows(SecurityException.class,()->f.actions.prepareNativeSend(other.task,"recipient@example.test","subject","body"));}}
 @Test public void cancellationCallsStopOnceButNeverSetsNativeEnd()throws Exception{try(F f=new F()){OfficialMailActions.Operation o=f.send();f.actions.dispatchPreparedOnce(o);f.task.client().requestCancellation();assertEquals(OfficialMailActions.HandoffObservation.CANCEL_REQUESTED_NOT_ENDED,f.actions.requestStopOwned(o));assertEquals(1,f.stops.get());assertFalse(f.task.nativeOwner().hasReportedActualDomainEnd());assertThrows(SecurityException.class,()->f.actions.requestStopOwned(o));}}
 @Test public void releaseRequiresActualOwnerEndNotBackendReturn()throws Exception{try(F f=new F()){OfficialMailActions.Operation o=f.send();f.actions.dispatchPreparedOnce(o);assertThrows(SecurityException.class,()->f.actions.releaseAfterActualNativeOwnerEnd(o));f.task.nativeOwner().reportActualDomainChainEnd(Cancellation.EndReason.UNDERLYING_RETURNED);f.actions.releaseAfterActualNativeOwnerEnd(o);assertEquals(OfficialMailActions.HandoffObservation.RETIRED_ACTUAL_OWNER_END,o.handoffObservation());assertThrows(SecurityException.class,o::nativePlainBody);}}
 @Test public void headerInjectionBrokenUnicodeAndUnboundedBodiesRejected()throws Exception{try(F f=new F()){assertThrows(IllegalArgumentException.class,()->f.actions.prepareNativeSend(f.task,"x@example.test\r\nBcc:secret","s","b"));assertThrows(IllegalArgumentException.class,()->f.actions.prepareNativeSend(f.task,"x@example.test","s\r\nbad","b"));assertThrows(IllegalArgumentException.class,()->f.actions.prepareNativeSend(f.task,"x@example.test","s","\ud800"));assertThrows(IllegalArgumentException.class,()->f.actions.prepareNativeSend(f.task,"x@example.test","s",new String(new char[65537])));}}
 @Test public void noDefaultAdapterOrPublicOperationConstructor()throws Exception{try(F f=new F()){assertEquals(0,OfficialMailActions.Operation.class.getConstructors().length);assertThrows(IllegalArgumentException.class,()->new OfficialMailActions(f.scope,null,null));}}
}
